pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;

    function setUp() public {
        c = new airPort();
    }

    function testFuzz_property(address from, address[] memory tos, uint256 v) public {
        // Admissible domain: at least one recipient, well-formed arguments.
        vm.assume(tos.length > 0);

        // Deploy a helper that always accepts the low-level transferFrom calls.
        Acceptor a = new Acceptor();

        // Both P and M should complete and return; capture the return value.
        bool ok;
        bool result;
        try c.transfer(from, address(a), tos, v) returns (bool r) {
            ok = true;
            result = r;
        } catch {
            ok = false;
        }

        // The reference C always returns true when it completes normally.
        // The mutant M returns false on a successful non-reverting call.
        assertTrue(!ok || result);
    }
}

// Minimal adversarial counterparty: accepts every low-level call.
contract Acceptor {
    fallback() external payable {}
}
